/**
 * ======================================================================
 * 【基本说明】：
 *  MobileIMSDK-Web版服务端的MQ消息中间件服务提供者实现类。
 *
 *  【本文件中实现的功能有】：
 *  1）一个消息生产者；
 *  2）一个消息消费者；
 *  3）（与MQ服务器）断线重连和恢复能力；
 *  [4）发送出错暂存到缓存数组（内存中），并在下次重连正常时自动重发；]
 *  5）遵照官方的最佳实践：一个连接（connection）、两个channel（一个用于生产者、一个用于消费者）；
 *  6）消费者手动ACK能力：业务层处理不成功可重新放回队列。
 *
 * 【基本用法】：
 * var MQ4桥接Provider = require('./im-mq-provider');
 * ======================================================================
 */


var amqp = require('amqplib/callback_api');
var config = require('../j_conf/config');
var logger = require('../j_conf/log').logger;
// MQ连接是否“正在”或“已经”start()，本标识用于防止在断线重连时出现两个循环调用start的线程
var running = false;
// if the connection is closed or fails to be established at all, we will reconnect
var amqpConn = null;
var pubChannel = null;

/* ##### 20160919 by js：为了让publish调用时能准确地反应出是否发送成功（而不需要在没发送成功时自动再次发送）
   #####                 ，暂时关闭了此离线再发功能，也许以后的其它逻辑中用的上，但还是暂时取消了相关代码！！
   #####                 【JS认为】桥接转发如不成功就应该立即由调用者知道，不然有此离线功能的话就会导致为何消息
   #####                 报已发出，但就是没有收到的问题，这对调试和用户体验都不利！*/
//var offlinePubQueue = [];

// MQ中间件收到桥接消息时的回调函数
var callBack_forWork = null;


/**
 * MQ中间件服务提供者的启动方法。
 */
function start() {
    // 防止被重复运行（根据下面的产生err即重新start的代码逻辑，如无本判断则会发生重启重启哦，不信仔细看代码！）
    if(running) {
        logger.warn('[3-MQ4桥接] - 【注意】MQ服务正在或已经start()，本次start()将被忽略！running=%s', running);
        return;
    }

    // 设置“正在”或“已经”start()标识
    running = true;

    logger.debug('[3-MQ4桥接] - [start()中] 要连接的MQ服务器地址：%s', config.im_mq_server_url + "?heartbeat=30");

    amqp.connect(config.im_mq_server_url + "?heartbeat=30", function(err, conn) {
        if (err) {
            running = false;
            logger.error('[3-MQ4桥接] - [start()中] amqp.connect出错了，回调中err.message：%s 【3秒后重新start重试】', err.message);
            return setTimeout(start, 3000);
        }

        // 连接成功后注册error事件监听
        conn.on("error", function(err) {
            logger.error('[3-MQ4桥接] - [start()中] conn.on("error")事件触发了，err：%s ', JSON.stringify(err));

            if (err.message !== "Connection closing") {
                console.error("[3-AMQP] - [start()中] conn error", err.message);
            }
        });

        // 连接成功后注册close事件监听
        conn.on("close", function() {
            running = false;
            logger.error('[3-MQ4桥接] - [start()中] conn.on("close")事件触发了，表示连接已关闭！【3秒后重新start重试】');
            return setTimeout(start, 3000);
        });

        logger.info("[3-MQ4桥接] - [start()中] 与RabittMQ服务器的连接成功完成！【OK】");
        amqpConn = conn;

        // 连接成功后要做的事
        whenConnected();
    });
}

function whenConnected() {
    startPublisher();
    startWorker();
}

